import { DomainError } from "./errors";

export type OrderState = "placed" | "paid" | "packed" | "shipped" | "delivered" | "cancelled";

export interface OrderLine {
  productId: string;
  quantity: number;
}

const NEXT_STATE: Readonly<Record<Exclude<OrderState, "cancelled">, OrderState | undefined>> = {
  placed: "paid",
  paid: "packed",
  packed: "shipped",
  shipped: "delivered",
  delivered: undefined,
};

export class Order {
  public constructor(
    public readonly id: string,
    public readonly customerId: string,
    public readonly lines: readonly OrderLine[],
    private currentState: OrderState = "placed",
  ) {
    if (!id || !customerId || lines.length === 0) {
      throw new DomainError("Order id, customer id, and at least one item are required");
    }
    for (const line of lines) {
      if (!line.productId || !Number.isInteger(line.quantity) || line.quantity <= 0) {
        throw new DomainError("Each order item needs a product id and positive integer quantity");
      }
    }
  }

  public get state(): OrderState {
    return this.currentState;
  }

  public advanceTo(nextState: OrderState): void {
    if (this.currentState === "cancelled" || NEXT_STATE[this.currentState] !== nextState) {
      throw new DomainError(`Order ${this.id} cannot move from ${this.currentState} to ${nextState}`);
    }
    this.currentState = nextState;
  }

  public cancel(): void {
    if (this.currentState === "shipped" || this.currentState === "delivered" || this.currentState === "cancelled") {
      throw new DomainError(`Order ${this.id} cannot be cancelled from ${this.currentState}`);
    }
    this.currentState = "cancelled";
  }
}

